/* Test-only raw float decoder for independently extracted Ogg packets. */
#include "lamp-test.h"
#include "speex/speex.h"
#include "speex/speex_header.h"
#include "speex/speex_stereo.h"
#include "speex/speex_callbacks.h"
static int read32(FILE*f,unsigned*v){unsigned char b[4];if(fread(b,1,4,f)!=4)return 0;*v=(unsigned)b[0]|(unsigned)b[1]<<8|(unsigned)b[2]<<16|(unsigned)b[3]<<24;return 1;}
int lamp_main(int argc,lamp_char**argv){if(argc!=3)return 2;FILE*in=lamp_fopen(argv[1],LT("rb")),*out=lamp_fopen(argv[2],LT("wb"));if(!in||!out)return 2;unsigned size,count;if(!read32(in,&size)||size<80||size>65536)return 2;unsigned char*head=malloc(size);if(!head||fread(head,1,size,in)!=size||!read32(in,&count)||count>100000)return 2;SpeexHeader*h=speex_packet_to_header((char*)head,size);if(!h||h->mode<0||h->mode>2||h->nb_channels<1||h->nb_channels>2)return 2;void*dec=speex_decoder_init(speex_lib_get_mode(h->mode));if(!dec)return 2;SpeexStereoState stereo;speex_stereo_state_reset(&stereo);if(h->nb_channels==2){SpeexCallback cb={SPEEX_INBAND_STEREO,speex_std_stereo_request_handler,&stereo};if(speex_decoder_ctl(dec,SPEEX_SET_HANDLER,&cb))return 2;}unsigned channels=h->nb_channels,n=160u<<h->mode,group=h->frames_per_packet?h->frames_per_packet:1;uint64_t frames=0;SpeexBits b;speex_bits_init(&b);for(unsigned i=0;i<count;i++){if(!read32(in,&size)||size>1048576)return 2;unsigned char*p=malloc(size);if(!p||fread(p,1,size,in)!=size)return 2;speex_bits_read_from(&b,(char*)p,size);free(p);for(unsigned j=0;j<group;j++){if(speex_bits_remaining(&b)<5||speex_bits_peek_unsigned(&b,5)==15)break;float pcm[1280],stereo_pcm[1280];if(speex_decode(dec,&b,pcm))return 1;if(channels==2)speex_decode_stereo(pcm,n,&stereo);for(unsigned k=0;k<n;k++){stereo_pcm[k*2]=pcm[k*channels]*(1.f/32768);stereo_pcm[k*2+1]=pcm[k*channels+(channels==2)]*(1.f/32768);}if(fwrite(stereo_pcm,8,n,out)!=n)return 2;frames+=n;}}speex_bits_destroy(&b);speex_decoder_destroy(dec);speex_header_free(h);free(head);fclose(in);fclose(out);printf("{\"frames\":%llu}\n",(unsigned long long)frames);return 0;}
